# tablica: każdy element przesuwa się o jedno miejsce
def wstaw_na_poczatek_tablicy(tab, x):
    tab.append(None)
    for i in range(len(tab) - 1, 0, -1):
        tab[i] = tab[i - 1]      # n przesunięć
    tab[0] = x

